import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, nowIso } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const jsonHeaders = { 'content-type': 'application/json; charset=utf-8' };
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, jsonHeaders);
  res.end(JSON.stringify(body));
}
function apiError(res: ServerResponse, status: number, code: string, message: string, fields?: {field:string; message:string}[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function bodyText(req: IncomingMessage): Promise<string> {
  let text = '';
  for await (const chunk of req) {
    text += chunk.toString();
    if (text.length > 64 * 1024) throw new Error('too_large');
  }
  return text;
}

const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health' && req.method === 'GET') {
    const heartbeat = db.prepare('SELECT at FROM worker_heartbeat WHERE singleton=1').get() as { at?: number } | undefined;
    send(res, 200, { status: 'ok', worker: heartbeat && Date.now() - Number(heartbeat.at) <= 3000 ? 'up' : 'down' }); return;
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string, unknown>[];
    send(res, 200, { jobs: rows.map(toJob) }); return;
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const fields: { field: string; message: string }[] = [];
    const type = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(type)) fields.push({ field: 'Content-Type', message: 'Must be application/json.' });
    const rawKey = req.headers['idempotency-key'];
    const key = Array.isArray(rawKey) ? rawKey[0] : rawKey;
    if (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key)) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1 to 128 letters, numbers, underscores, or hyphens.' });
    let parsed: unknown;
    try { parsed = JSON.parse(await bodyText(req)); }
    catch { fields.push({ field: 'body', message: 'Body must be valid JSON and no larger than 64 KB.' }); }
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      if (parsed !== undefined) fields.push({ field: 'body', message: 'Body must be a JSON object.' });
    }
    let input: unknown, steps: unknown = 5, failAttempts: unknown = 0;
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      const obj = parsed as Record<string, unknown>;
      for (const name of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(name)) fields.push({ field: name, message: 'Unknown field.' });
      input = obj.input; if ('steps' in obj) steps = obj.steps; if ('failAttempts' in obj) failAttempts = obj.failAttempts;
      if (!('input' in obj)) fields.push({ field: 'input', message: 'Required.' });
    }
    if (input !== undefined && (typeof input !== 'string' || input.length < 1 || input.length > 1000 || input.trim().length === 0)) fields.push({ field: 'input', message: 'Must be a non-whitespace string of 1 to 1000 characters.' });
    if (!Number.isInteger(steps) || (steps as number) < 1 || (steps as number) > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
    if (!Number.isInteger(failAttempts) || (failAttempts as number) < 0 || (failAttempts as number) > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
    if (fields.length) { apiError(res, 400, 'invalid_request', 'The request is invalid.', fields); return; }
    const payload = JSON.stringify({ input, steps, failAttempts });
    if (key !== undefined) {
      const prior = db.prepare('SELECT i.payload, j.* FROM idempotency i JOIN jobs j ON j.id=i.job_id WHERE i.key=?').get(key) as (Record<string, unknown> & { payload: string }) | undefined;
      if (prior) {
        if (prior.payload !== payload) { apiError(res, 409, 'idempotency_conflict', 'This key was already used with a different payload.'); return; }
        send(res, 200, toJob(prior)); return;
      }
    }
    const id = randomUUID(), timestamp = nowIso();
    db.exec('BEGIN IMMEDIATE');
    try {
      // Recheck under the write lock so concurrent submissions cannot create duplicates.
      if (key !== undefined) {
        const prior = db.prepare('SELECT i.payload, j.* FROM idempotency i JOIN jobs j ON j.id=i.job_id WHERE i.key=?').get(key) as (Record<string, unknown> & { payload: string }) | undefined;
        if (prior) {
          db.exec('COMMIT');
          if (prior.payload !== payload) apiError(res, 409, 'idempotency_conflict', 'This key was already used with a different payload.');
          else send(res, 200, toJob(prior));
          return;
        }
      }
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,available_at)
        VALUES(?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0)`).run(id, input as string, steps as number, failAttempts as number, timestamp, timestamp);
      if (key !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key, payload, id);
      db.exec('COMMIT');
    } catch (error) { db.exec('ROLLBACK'); throw error; }
    const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Record<string, unknown>;
    send(res, 201, toJob(row)); return;
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match && req.method === 'GET') {
    let id: string; try { id = decodeURIComponent(match[1]!); } catch { apiError(res, 404, 'not_found', 'Job not found.'); return; }
    const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Record<string, unknown> | undefined;
    if (!row) apiError(res, 404, 'not_found', 'Job not found.'); else send(res, 200, toJob(row));
    return;
  }
  const known = pathname === '/' || pathname === '/health' || pathname === '/api/jobs' || /^\/api\/jobs\/[^/]+$/.test(pathname);
  apiError(res, known ? 405 : 404, known ? 'method_not_allowed' : 'not_found', known ? 'Method not allowed.' : 'Route not found.');
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));

